package com.matejpcs.netflared;import com.mojang.brigadier.arguments.StringArgumentType;import net.minecraft.commands.*;import net.minecraft.network.chat.Component;import net.minecraft.server.MinecraftServer;import net.neoforged.bus.api.SubscribeEvent;import net.neoforged.fml.common.Mod;import net.neoforged.neoforge.common.NeoForge;import net.neoforged.neoforge.event.RegisterCommandsEvent;import net.neoforged.neoforge.event.server.ServerStartedEvent;import net.neoforged.neoforge.event.server.ServerStoppingEvent;import java.nio.file.Path;@Mod("netflared")public final class NetflaredNeoForge{private NetflaredCore core;private MinecraftServer server;public NetflaredNeoForge(){NeoForge.EVENT_BUS.register(this);}@SubscribeEvent public void commands(RegisterCommandsEvent e){e.getDispatcher().register(Commands.literal("netflared").requires(source -> source.hasPermission(4)).executes(x->{run(x.getSource(),new String[0]);return 1;}).then(Commands.literal("status").executes(x->{run(x.getSource(),new String[]{"status"});return 1;})).then(Commands.literal("info").executes(x->{run(x.getSource(),new String[]{"info"});return 1;})).then(Commands.literal("connect").executes(x->{run(x.getSource(),new String[]{"connect"});return 1;})).then(Commands.literal("disconnect").executes(x->{run(x.getSource(),new String[]{"disconnect"});return 1;})).then(Commands.literal("reset").executes(x->{run(x.getSource(),new String[]{"reset"});return 1;})).then(Commands.literal("setup").then(Commands.argument("args",StringArgumentType.greedyString()).executes(x->{run(x.getSource(),new String[]{"setup",StringArgumentType.getString(x,"args")});return 1;}))));}@SubscribeEvent public void started(ServerStartedEvent e){server=e.getServer();try{core=new NetflaredCore(Path.of("config","netflared"),()->new NetflaredCore.ServerInfo(server.getPort(),"neoforge"),server::execute);core.autoConnect();}catch(Exception x){server.sendSystemMessage(Component.literal("Netflared failed to initialize: "+x.getMessage()));}}@SubscribeEvent public void stopping(ServerStoppingEvent e){if(core!=null)core.shutdown();}private void run(CommandSourceStack s,String[]a){if(core==null){s.sendFailure(Component.literal("Netflared is not initialized."));return;}core.handle(new NetflaredCore.Sender(){public boolean admin(){return true;}public void send(String m){s.sendSystemMessage(Component.literal(m.replaceAll("§.","")));}},a);}}